prompt:
The library function `ledger::pay_all` returns how many transfers succeeded but its contract does not bound that number. Add to its postcondition that the result is at most a.len(), keeping everything else.

Required signature (in unit `ledger`):
fn pay_all(a: &mut [i64], from: usize, x: i64) -> (r: usize)

reference.code:
spec fn paid_ok(a: &[i64], r: usize) -> bool { r <= a.len() }

#[effects(pure)]
#[uses(cap_ok, acct, amount_ok, paid_ok)]
fn pay_all(a: &mut [i64], from: usize, x: i64) -> (r: usize)
    requires cap_ok(a), acct(a, from), amount_ok(x),
    ensures cap_ok(a), paid_ok(a, r),
{
    let mut paid: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), paid <= k, from < a.len(), cap_ok(a),
        decreases a.len() - k,
    {
        if transfer(a, from, k, x) {
            paid = paid + 1;
        }
        k = k + 1;
    }
    paid
}
